import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const ROLES = ['Authorized User', 'Record Manager', 'Auditor', 'Admin'];
const roleDesc = {
  'Authorized User': 'View and download documents',
  'Record Manager': 'Upload and manage documents',
  'Auditor': 'View logs and generate reports',
  'Admin': 'Full system access'
};

export default function Register() {
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'Authorized User' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPass, setShowPass] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await register(form.name, form.email, form.password, form.role);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <div style={styles.cardHeader}>
          <div style={styles.logo}>🗂 DRMS</div>
          <h2 style={styles.title}>Create Account</h2>
          <p style={styles.sub}>Join the Digital Records Management System</p>
        </div>

        {error && <div style={styles.errorBox}><span>⚠️</span> {error}</div>}

        <form onSubmit={handleSubmit}>
          <div style={styles.grid}>
            <div style={styles.field}>
              <label style={styles.label}>Full Name</label>
              <div style={styles.inputWrap}>
                <span style={styles.icon}>👤</span>
                <input style={styles.input} placeholder="Your full name" value={form.name}
                  onChange={e => setForm({ ...form, name: e.target.value })} required />
              </div>
            </div>
            <div style={styles.field}>
              <label style={styles.label}>Email Address</label>
              <div style={styles.inputWrap}>
                <span style={styles.icon}>✉️</span>
                <input style={styles.input} type="email" placeholder="you@example.com" value={form.email}
                  onChange={e => setForm({ ...form, email: e.target.value })} required />
              </div>
            </div>
          </div>

          <div style={styles.field}>
            <label style={styles.label}>Password</label>
            <div style={styles.inputWrap}>
              <span style={styles.icon}>🔑</span>
              <input style={styles.input} type={showPass ? 'text' : 'password'} placeholder="Create a strong password"
                value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required />
              <span style={styles.eyeBtn} onClick={() => setShowPass(!showPass)}>{showPass ? '🙈' : '👁'}</span>
            </div>
          </div>

          <div style={styles.field}>
            <label style={styles.label}>Select Role</label>
            <div style={styles.roleGrid}>
              {ROLES.map(r => (
                <div key={r} style={{ ...styles.roleCard, ...(form.role === r ? styles.roleCardActive : {}) }}
                  onClick={() => setForm({ ...form, role: r })}>
                  <span style={styles.roleCheck}>{form.role === r ? '✅' : '⬜'}</span>
                  <div>
                    <div style={styles.roleName}>{r}</div>
                    <div style={styles.roleDesc}>{roleDesc[r]}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <button style={{ ...styles.btn, opacity: loading ? 0.7 : 1 }} type="submit" disabled={loading}>
            {loading ? '⏳ Creating account...' : '→  Create Account'}
          </button>
        </form>

        <p style={styles.footer}>Already have an account? <Link to="/login" style={styles.link}>Sign in</Link></p>
      </div>
    </div>
  );
}

const styles = {
  page: { display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: 'linear-gradient(135deg, #f0f2ff 0%, #faf5ff 100%)', padding: '24px' },
  card: { background: '#fff', borderRadius: '16px', padding: '40px', boxShadow: '0 4px 24px rgba(0,0,0,0.08)', width: '100%', maxWidth: '560px' },
  cardHeader: { textAlign: 'center', marginBottom: '28px' },
  logo: { fontSize: '20px', fontWeight: '700', color: '#4f46e5', marginBottom: '12px' },
  title: { fontSize: '24px', fontWeight: '700', color: '#1e293b', marginBottom: '4px' },
  sub: { color: '#64748b', fontSize: '14px' },
  errorBox: { display: 'flex', alignItems: 'center', gap: '8px', background: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626', padding: '10px 14px', borderRadius: '8px', fontSize: '13px', marginBottom: '16px' },
  grid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' },
  field: { marginBottom: '18px' },
  label: { display: 'block', fontSize: '13px', fontWeight: '600', color: '#374151', marginBottom: '6px' },
  inputWrap: { position: 'relative', display: 'flex', alignItems: 'center' },
  icon: { position: 'absolute', left: '12px', fontSize: '14px' },
  input: { width: '100%', padding: '10px 12px 10px 36px', border: '1.5px solid #e2e8f0', borderRadius: '8px', fontSize: '14px', outline: 'none', background: '#f8fafc', boxSizing: 'border-box' },
  eyeBtn: { position: 'absolute', right: '12px', cursor: 'pointer', fontSize: '15px' },
  roleGrid: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' },
  roleCard: { display: 'flex', alignItems: 'flex-start', gap: '8px', padding: '12px', border: '1.5px solid #e2e8f0', borderRadius: '8px', cursor: 'pointer', transition: 'all 0.2s', background: '#f8fafc' },
  roleCardActive: { border: '1.5px solid #4f46e5', background: '#f0f0ff' },
  roleCheck: { fontSize: '14px', marginTop: '1px' },
  roleName: { fontSize: '13px', fontWeight: '600', color: '#1e293b' },
  roleDesc: { fontSize: '11px', color: '#94a3b8', marginTop: '2px' },
  btn: { width: '100%', padding: '12px', background: 'linear-gradient(135deg, #4f46e5, #7c3aed)', color: '#fff', border: 'none', borderRadius: '8px', fontSize: '15px', fontWeight: '600', cursor: 'pointer', marginTop: '4px' },
  footer: { textAlign: 'center', marginTop: '20px', fontSize: '13px', color: '#64748b' },
  link: { color: '#4f46e5', fontWeight: '600' }
};
